SELECT status, DATE_TRUNC('MONTH', order_date) AS order_month, SUM(CASE WHEN channel = 'store' THEN amount ELSE 0 END) AS store_amount, MAX(discount) AS max_discount, ROUND((100 * SUM(CASE WHEN channel = 'mobile' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_mobile FROM orders WHERE discount IS NULL AND store_id IS NOT NULL GROUP BY status, DATE_TRUNC('MONTH', order_date) ORDER BY pct_mobile DESC;
